package EX18.EX87;

import java.math.BigDecimal;
import java.sql.Connection;
import java.sql.Statement;

public class Main {
    public static void main(String[] args) throws Exception {
        try (Connection conn = ConnectionFactory.getConnection();
             Statement st = conn.createStatement()) {
            st.execute("CREATE TABLE produtos (" +
                    "id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, " +
                    "descricao VARCHAR(200) NOT NULL, " +
                    "preco_unitario DECIMAL(12,2) NOT NULL, " +
                    "quantidade_estoque INT NOT NULL)");
        }

        GenericDAO<Produto, Long> dao = new ProdutoDAOImpl();

        Produto p = new Produto("Teclado", new BigDecimal("150.00"), 10);
        dao.salvar(p);
        System.out.println("Criado: " + p);

        System.out.println("Busca: " + dao.buscarPorId(p.getId()).orElseThrow());
        System.out.println("Inexistente: " + dao.buscarPorId(999L).isPresent());

        p.setPrecoUnitario(new BigDecimal("139.90"));
        p.setQuantidadeEstoque(8);
        dao.atualizar(p);
        System.out.println("Atualizado: " + dao.buscarPorId(p.getId()).orElseThrow());

        dao.deletarPorId(p.getId());
        System.out.println("Após delete: " + dao.listarTodos());
    }
}
